package sharedobjects

import "math"

// OneAtATime is the Bob Jenkins "one-at-a-time" mixing function used
// historically by the Java shared-objects runtime (see
// `src/shared/HashFunctions.java#oneAtATime`). It is the default mixer
// for term constructors generated by the .gom → .go backend.
//
// The input is the list of sub-hashes of a term's arguments, followed
// (by convention in the Java code) by the hash of the head symbol.
func OneAtATime(parts []uint32) uint32 {
	var h uint32
	for _, p := range parts {
		h += p
		h += h << 10
		h ^= h >> 6
	}
	h += h << 3
	h ^= h >> 11
	h += h << 15
	return h
}

// MixSymbol is a small helper for hashing a (symbol, args…) tuple.
// It produces the same bit pattern as `OneAtATime(append(argHashes, symbolHash))`
// but without an extra allocation.
func MixSymbol(symbol uint32, args []uint32) uint32 {
	var h uint32
	for _, p := range args {
		h += p
		h += h << 10
		h ^= h >> 6
	}
	h += symbol
	h += h << 10
	h ^= h >> 6
	h += h << 3
	h ^= h >> 11
	h += h << 15
	return h
}

// StringHash returns a 32-bit hash of s using the same one-at-a-time
// mixer; useful when a term's head is identified by a string symbol
// name rather than an interned int.
func StringHash(s string) uint32 {
	var h uint32
	for i := 0; i < len(s); i++ {
		h += uint32(s[i])
		h += h << 10
		h ^= h >> 6
	}
	h += h << 3
	h ^= h >> 11
	h += h << 15
	return h
}

// IntHash hashes a builtin integer (Gom's int and long, char as its code
// point) with the one-at-a-time mixer, without formatting it.
func IntHash(v int64) uint32 {
	u := uint64(v)
	return MixSymbol(uint32(u>>32), []uint32{uint32(u)})
}

// BoolHash hashes a builtin boolean.
func BoolHash(b bool) uint32 {
	if b {
		return IntHash(1)
	}
	return IntHash(0)
}

// Float64Hash hashes a builtin double through its IEEE 754 bits.
func Float64Hash(f float64) uint32 { return IntHash(int64(math.Float64bits(f))) }

// Float32Hash hashes a builtin float through its IEEE 754 bits.
func Float32Hash(f float32) uint32 { return IntHash(int64(math.Float32bits(f))) }
